export function maxProfit(prices: number[]): number {
  let minPrice = Infinity;
  let profit = 0;
  for (const price of prices) {
    if (price < minPrice) {
      minPrice = price;
    } else if (price - minPrice > profit) {
      profit = price - minPrice;
    }
  }
  return profit;
}
